/// rich-text-editor: Document notes
private struct RichTextEditorExample0: View {
    @State private var text: AttributedString = {
        let introduction: String = ["Ship the ", "new onboarding", " after the review on Thursday. See the ", "rollout guide", "."].joined()
        let tasks: [(label: String, done: Bool)] = [
            ("Update the help article", true),
            ("Tell the support team", false),
        ]
        var document = AttributedString()
        var heading = AttributedString("Release checklist" + "\n")
        heading.font = .title3.bold()
        document += heading
        var intro = AttributedString(introduction + "\n")
        if let range = intro.range(of: "new onboarding") { intro[range].font = .body.bold() }
        if let range = intro.range(of: "rollout guide") { intro[range].link = URL(string: "https://example.com/guide"); intro[range].underlineStyle = .single }
        document += intro
        for task in tasks {
            var line = AttributedString((task.done ? "☑\u{FE0E} " : "☐\u{FE0E} ") + task.label + "\n")
            if task.done { line.strikethroughStyle = .single }
            document += line
        }
        var quote = AttributedString("▎ " + "Keep the old flow behind a setting for one release.")
        quote.foregroundColor = .secondary
        document += quote
        return document
    }()

    var body: some View {
        if #available(iOS 26.0, macOS 26.0, *) {
            MonarchRichTextEditor(
                "Release notes",
                text: $text,
                prompt: "Write notes…",
                tools: [
                    [.bold, .italic, .strikethrough, .code],
                    [.heading(2), .heading(3)],
                    [.bulletList, .orderedList, .taskList],
                    [.link, .blockquote, .codeBlock],
                ]
            )
            .frame(height: 380)
        }
    }
}

/// rich-text-editor: A reply with inline tools and mentions
private struct RichTextEditorExample1: View {
    @State private var text = AttributedString()
    @State private var suggestions: [MonarchMentionItem] = []
    private let people = [MonarchMentionItem(id: "u1", label: "Ana Lopez", detail: "Design")]
    private func search(_ query: MonarchMentionQuery?) -> [MonarchMentionItem] {
        guard let query else { return [] }
        return people.filter { query.text.isEmpty || $0.label.localizedCaseInsensitiveContains(query.text) }
    }

    var body: some View {
        if #available(iOS 26.0, macOS 26.0, *) {
            MonarchRichTextEditor(
                "Reply",
                text: $text,
                prompt: "Reply to the thread",
                tools: MonarchEditorTool.inlineGroups,
                mentionItems: suggestions,
                onMentionSearch: { suggestions = search($0) }
            )
        }
    }
}

